import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Flow } from 'flow-sdk';
import { pipeline, env, RawImage } from '@huggingface/transformers';

// Transformers.js environment config for sandboxed iframe
env.allowLocalModels = false;
env.useBrowserCache = false;

// --- Design System Primitives ---

const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

const PillButton: React.FC<{
  icon?: React.ReactNode;
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid';
  onClick?: () => void;
  disabled?: boolean;
  className?: string;
}> = ({ icon, children, variant = 'filled', onClick, disabled, className = '' }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]} ${className}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

// --- Model Singleton ---

let segmenterPromise: Promise<any> | null = null;

async function getSegmenter(onProgress?: (progress: number) => void) {
  if (!segmenterPromise) {
    segmenterPromise = pipeline('image-segmentation', 'Xenova/modnet', {
      device: 'webgpu',
      progress_callback: (p: any) => {
        if (p.status === 'progress' && onProgress) {
          onProgress(p.progress);
        }
      },
    });
  }
  return segmenterPromise;
}

// --- Main App Component ---

export default function App() {
  const [inputImage, setInputImage] = useState<{ mediaId: string; dataUrl: string; name: string } | null>(null);
  const [outputImage, setOutputImage] = useState<{ mediaId: string; dataUrl: string; name: string } | null>(null);
  const [status, setStatus] = useState<'idle' | 'loading_model' | 'processing' | 'done' | 'error'>('idle');
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [saveState, setSaveState] = useState<'idle' | 'saving' | 'saved'>('idle');

  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      .checkerboard {
        background-color: #1a1a1a;
        background-image: linear-gradient(45deg, #222 25%, transparent 25%),
          linear-gradient(-45deg, #222 25%, transparent 25%),
          linear-gradient(45deg, transparent 75%, #222 75%),
          linear-gradient(-45deg, transparent 75%, #222 75%);
        background-size: 20px 20px;
        background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
      }
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif; letter-spacing: 0.1px; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleSelect = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      setInputImage({
        mediaId: media.mediaId,
        dataUrl: `data:${media.mimeType};base64,${media.base64}`,
        name: media.name
      });
      setOutputImage(null);
      setStatus('idle');
      setError(null);
    } catch (e) {
      console.error(e);
    }
  };

  const processImage = async () => {
    if (!inputImage) return;
    setStatus('loading_model');
    setProgress(0);
    setError(null);

    try {
      const segmenter = await getSegmenter((p) => setProgress(p));
      setStatus('processing');

      // 1. Load image as RawImage
      const image = await RawImage.fromURL(inputImage.dataUrl);

      // 2. Perform segmentation
      const output = await segmenter(image);
      const mask = output[0].mask; 

      // 3. Apply mask to original image on canvas
      const canvas = document.createElement('canvas');
      canvas.width = image.width;
      canvas.height = image.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true })!;

      // Draw original
      const originalCanvas = await image.toCanvas();
      ctx.drawImage(originalCanvas, 0, 0);

      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);

      // Resize mask to match image
      const maskResized = await mask.resize(image.width, image.height);

      // Map mask (0-255 grayscale) to Alpha channel
      for (let i = 0; i < imgData.data.length / 4; i++) {
        imgData.data[i * 4 + 3] = maskResized.data[i];
      }

      ctx.putImageData(imgData, 0, 0);

      // 4. Export as PNG (supports transparency)
      const dataUrl = canvas.toDataURL('image/png');
      const base64 = dataUrl.split(',')[1];

      // 5. Save to Flow (automatically saved to gallery)
      const saved = await Flow.save({
        base64,
        mimeType: 'image/png',
        name: `${inputImage.name} (No BG)`
      });

      setOutputImage({
        mediaId: saved.mediaId,
        dataUrl,
        name: `${inputImage.name}_nobg`
      });
      setStatus('done');
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Background removal failed');
      setStatus('error');
    }
  };

  const downloadResult = async () => {
    if (!outputImage || saveState !== 'idle') return;
    setSaveState('saving');
    try {
      await Flow.download({
        base64: outputImage.dataUrl.split(',')[1],
        mimeType: 'image/png',
        filename: `${outputImage.name}.png`
      });
      setSaveState('saved');
      setTimeout(() => setSaveState('idle'), 2000);
    } catch (e) {
      setSaveState('idle');
    }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] overflow-hidden">
      {/* Left Panel */}
      <div className="border-r border-[rgba(218,220,224,0.15)] flex flex-col justify-between p-[10px] py-[12px] w-[300px] h-full shrink-0">
        <div className="flex flex-col gap-[24px]">
          {/* Input Section */}
          <div className="flex flex-col gap-2">
            <SectionLabel>Input media</SectionLabel>
            <PillButton 
              icon={<span className="material-symbols-outlined text-[18px]">photo_library</span>} 
              variant="filled"
              onClick={handleSelect}
              disabled={status === 'loading_model' || status === 'processing'}
            >
              {inputImage ? 'Replace Image' : 'Select Image'}
            </PillButton>

            {inputImage && (
              <div className="mt-2 rounded-xl overflow-hidden border border-[#595959] aspect-square bg-[#1a1a1a] relative group">
                <img src={inputImage.dataUrl} className="w-full h-full object-contain" alt="Input" />
                <div className="absolute bottom-0 left-0 right-0 bg-black/60 p-2 text-[10px] text-white/80 truncate">
                  {inputImage.name}
                </div>
              </div>
            )}
          </div>

          {/* Controls Section */}
          <div className="flex flex-col gap-2">
            <SectionLabel>Processing</SectionLabel>
            <PillButton
              icon={<span className="material-symbols-outlined text-[18px]">auto_fix_high</span>}
              variant="solid"
              onClick={processImage}
              disabled={!inputImage || status === 'loading_model' || status === 'processing'}
            >
              {status === 'loading_model' ? 'Downloading Model...' : status === 'processing' ? 'Processing...' : 'Remove Background'}
            </PillButton>

            {(status === 'loading_model' || status === 'processing') && (
              <div className="w-full mt-2">
                <div className="flex justify-between text-[10px] text-white/40 mb-1 px-1">
                  <span>{status === 'loading_model' ? 'Model Download' : 'Segmenting'}</span>
                  <span>{Math.round(progress * 100)}%</span>
                </div>
                <div className="h-1 bg-[#1a1a1a] rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-white transition-all duration-300 ease-out"
                    style={{ width: `${progress * 100}%` }}
                  />
                </div>
              </div>
            )}

            {error && (
              <div className="p-2 rounded-lg bg-red-500/10 border border-red-500/20 text-red-400 text-[10px] mt-2">
                {error}
              </div>
            )}
          </div>
        </div>

        {/* Bottom Actions */}
        <div className="flex flex-col gap-[5px] pt-2 border-t border-[rgba(218,220,224,0.15)]">
          <PillButton 
            variant="outline" 
            icon={<span className="material-symbols-outlined text-[18px]">download</span>}
            onClick={downloadResult}
            disabled={!outputImage || saveState !== 'idle'}
          >
            {saveState === 'saved' ? 'Downloaded ✓' : saveState === 'saving' ? 'Downloading...' : 'Download PNG'}
          </PillButton>
        </div>
      </div>

      {/* Main Viewport */}
      <div className="flex-1 h-full flex flex-col relative overflow-hidden bg-[#0a0a0a]">
        <div className="flex-1 relative flex items-center justify-center p-8">
          {!inputImage && !outputImage && (
            <div className="text-center">
              <span className="material-symbols-outlined text-[64px] text-white/10 mb-4">image</span>
              <p className="text-white/30 text-sm font-medium">Select an image to start</p>
            </div>
          )}

          {(inputImage || outputImage) && (
            <div className="w-full h-full flex flex-col gap-6 max-w-4xl mx-auto">
              <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-6 min-h-0">
                {/* Before */}
                <div className="flex flex-col gap-3 min-h-0">
                  <div className="text-[11px] font-medium text-white/40 uppercase tracking-widest text-center">Original</div>
                  <div className="flex-1 bg-[#1a1a1a] rounded-2xl border border-[rgba(218,220,224,0.1)] overflow-hidden relative shadow-2xl">
                    {inputImage && <img src={inputImage.dataUrl} className="w-full h-full object-contain" alt="Original" />}
                  </div>
                </div>

                {/* After */}
                <div className="flex flex-col gap-3 min-h-0">
                  <div className="text-[11px] font-medium text-white/40 uppercase tracking-widest text-center">Transparent Result</div>
                  <div className="flex-1 checkerboard rounded-2xl border border-[rgba(218,220,224,0.1)] overflow-hidden relative shadow-2xl group">
                    {outputImage ? (
                      <>
                        <img src={outputImage.dataUrl} className="w-full h-full object-contain animate-in fade-in zoom-in-95 duration-500" alt="Result" />
                        <button 
                          onClick={downloadResult}
                          disabled={saveState !== 'idle'}
                          className="absolute top-4 right-4 z-10 w-10 h-10 rounded-xl bg-black/60 hover:bg-black/80 backdrop-blur-md border border-white/10 flex items-center justify-center text-white transition-all active:scale-95 disabled:opacity-50"
                          title="Download Result"
                        >
                          <span className="material-symbols-outlined text-[20px]">
                            {saveState === 'saved' ? 'check' : 'download'}
                          </span>
                        </button>
                      </>
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                         {status === 'processing' || status === 'loading_model' ? (
                           <div className="flex flex-col items-center gap-4">
                              <div className="w-12 h-12 border-2 border-white/10 border-t-white rounded-full animate-spin" />
                              <span className="text-white/20 text-[10px] animate-pulse">Removing background...</span>
                           </div>
                         ) : (
                           <span className="material-symbols-outlined text-white/5 text-[48px]">auto_fix_high</span>
                         )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
